import math

def two_asset_variance(weight,vol1,vol2,correlation):
    # Same-horizon return volatilities;weights(weight,1-weight),no leverage.
    for value,low,high in ((weight,0.0,1.0),(vol1,0.0,2.0),(vol2,0.0,2.0),(correlation,-1.0,1.0)):
        if type(value) is not float or not math.isfinite(value) or not low<=value<=high:
            raise ValueError("invalid covariance-model input")
    a=weight*vol1
    b=(1.0-weight)*vol2
    # Two-factor decomposition equals a*a+b*b+2*a*b*correlation.
    return (a+b*correlation)**2+b*b*(1.0-correlation*correlation)

print(f"{two_asset_variance(0.5,0.2,0.3,0.0):.6f}")
print(two_asset_variance(0.5,0.2,0.2,-1.0))
print(f"{two_asset_variance(0.5,0.2,0.3,1.0):.6f}")
